#include <stdio.h>

#define MAXN 16

/* out 是 1..n 的一个排列，判断它是否为合法出栈序列 */
int IsValidPop(const int *out, int n)
{
    int st[MAXN], top = 0, next = 1, i;
    for (i = 0; i < n; i++) {
        while (top == 0 || st[top - 1] != out[i]) {
            if (next > n) return 0;        /* 没有元素可再入栈 */
            st[top++] = next++;
        }
        top--;                             /* 弹出栈顶 */
    }
    return 1;
}

int main(void)
{
    int s1[3] = {3, 2, 1};
    int s2[3] = {3, 1, 2};
    int s3[3] = {1, 3, 2};
    int s4[4] = {4, 2, 3, 1};
    int s5[4] = {4, 1, 3, 2};

    printf("3 2 1 -> %s\n", IsValidPop(s1, 3) ? "合法" : "非法");
    printf("3 1 2 -> %s\n", IsValidPop(s2, 3) ? "合法" : "非法");
    printf("1 3 2 -> %s\n", IsValidPop(s3, 3) ? "合法" : "非法");
    printf("4 2 3 1 -> %s\n", IsValidPop(s4, 4) ? "合法" : "非法");
    printf("4 1 3 2 -> %s\n", IsValidPop(s5, 4) ? "合法" : "非法");
    return 0;
}

#include <stdio.h>

#define N 3

static int st[N + 1], top = 0;
static int out[N], len = 0;
static int pushed = 0;
static int cnt = 0;

void dfs(void)
{
    int i, v;
    if (len == N) {                       /* N 个元素全部出栈 */
        cnt++;
        printf("%d: ", cnt);
        for (i = 0; i < N; i++) printf("%d", out[i]);
        printf("\n");
        return;
    }
    if (pushed < N) {                     /* 分支一：入栈 */
        st[top++] = ++pushed;
        dfs();
        top--; pushed--;                  /* 回溯 */
    }
    if (top > 0) {                        /* 分支二：出栈 */
        v = st[--top];
        out[len++] = v;
        dfs();
        len--; st[top++] = v;             /* 回溯 */
    }
}

int main(void)
{
    dfs();
    printf("n=%d 共 %d 种出栈序列 = C(2n,n)/(n+1)\n", N, cnt);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define STACK_INIT_SIZE 4
#define STACKINCREMENT  2

typedef int ElemType;
typedef struct {
    ElemType *base;
    ElemType *top;
    int       stacksize;
} SqStack;

int InitStack(SqStack *S)
{
    S->base = (ElemType *)malloc(STACK_INIT_SIZE * sizeof(ElemType));
    if (S->base == NULL) return 0;
    S->top = S->base;                  /* 空栈 */
    S->stacksize = STACK_INIT_SIZE;
    return 1;
}

int StackEmpty(const SqStack *S) { return S->top == S->base; }
int StackLen  (const SqStack *S) { return (int)(S->top - S->base); }

int Push(SqStack *S, ElemType e)
{
    ElemType *newbase;
    if (StackLen(S) >= S->stacksize) {         /* 栈满，扩容 */
        newbase = (ElemType *)realloc(S->base,
                    (size_t)(S->stacksize + STACKINCREMENT) * sizeof(ElemType));
        if (newbase == NULL) return 0;
        S->base = newbase;                     /* base 可能已搬家 */
        S->top  = S->base + S->stacksize;      /* top 必须重算 */
        S->stacksize += STACKINCREMENT;
        printf("  [realloc -> stacksize=%d]\n", S->stacksize);
    }
    *S->top++ = e;                             /* 先赋值，后上移 */
    return 1;
}

int Pop(SqStack *S, ElemType *e)
{
    if (StackEmpty(S)) return 0;
    *e = *--S->top;                            /* 先下移，后取值 */
    return 1;
}

int main(void)
{
    SqStack S;
    ElemType e = 0;
    int i;
    if (!InitStack(&S)) { printf("malloc failed\n"); return 1; }

    for (i = 1; i <= 7; i++) { Push(&S, i * 10); printf("push %d len=%d\n", i*10, StackLen(&S)); }
    printf("stacksize=%d base!=NULL %d\n", S.stacksize, S.base != NULL);
    while (!StackEmpty(&S)) { Pop(&S, &e); printf("pop %d ", e); }
    printf("\nempty=%d\n", StackEmpty(&S));
    printf("pop on empty stack -> %s\n", Pop(&S, &e) ? "ok" : "failed");
    free(S.base);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXSIZE 6
typedef int ElemType;

typedef struct SNode { ElemType data; struct SNode *next; } SNode, *LinkStack;

int PushL(LinkStack *top, ElemType e)     /* 链栈入栈：头插 */
{
    SNode *s = (SNode *)malloc(sizeof(SNode));
    if (s == NULL) return 0;
    s->data = e;
    s->next = *top;
    *top = s;
    return 1;
}

int PopL(LinkStack *top, ElemType *e)     /* 链栈出栈：头删 */
{
    SNode *p = *top;
    if (p == NULL) return 0;
    *e = p->data;
    *top = p->next;
    free(p);
    return 1;
}

/* 两栈共享 base[0..MAXSIZE-1]：top1 从左往右，top2 从右往左 */
static ElemType base[MAXSIZE];
static int top1 = -1, top2 = MAXSIZE;

int Push1(ElemType e) { if (top1 + 1 == top2) return 0; base[++top1] = e; return 1; }
int Push2(ElemType e) { if (top1 + 1 == top2) return 0; base[--top2] = e; return 1; }

int main(void)
{
    LinkStack top = NULL;
    ElemType e = 0;
    int i;

    for (i = 1; i <= 4; i++) PushL(&top, i * 100);
    printf("链栈出栈(应为逆序):");
    while (PopL(&top, &e)) printf(" %d", e);
    printf("\n链栈已空 top==NULL ? %d\n", top == NULL);

    for (i = 1; i <= 3; i++) printf("Push1(%d)=%s ", i, Push1(i) ? "ok" : "full");
    printf("\n");
    for (i = 1; i <= 3; i++) printf("Push2(%d)=%s ", i, Push2(i) ? "ok" : "full");
    printf("\nPush1(4)=%s (top1=%d top2=%d 已相遇)\n",
           Push1(4) ? "ok" : "full", top1, top2);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXQSIZE 6          /* 少用一个单元，实际容量 5 */

typedef int ElemType;
typedef struct {
    ElemType *base;
    int front;
    int rear;
} SqQueue;

int InitQueue(SqQueue *Q)
{
    Q->base = (ElemType *)malloc(MAXQSIZE * sizeof(ElemType));
    if (Q->base == NULL) return 0;
    Q->front = Q->rear = 0;
    return 1;
}

int QueueEmpty (const SqQueue *Q) { return Q->front == Q->rear; }
int QueueFull  (const SqQueue *Q) { return (Q->rear + 1) % MAXQSIZE == Q->front; }
int QueueLength(const SqQueue *Q) { return (Q->rear - Q->front + MAXQSIZE) % MAXQSIZE; }

int EnQueue(SqQueue *Q, ElemType e)
{
    if (QueueFull(Q)) return 0;
    Q->base[Q->rear] = e;
    Q->rear = (Q->rear + 1) % MAXQSIZE;
    return 1;
}

int DeQueue(SqQueue *Q, ElemType *e)
{
    if (QueueEmpty(Q)) return 0;
    *e = Q->base[Q->front];
    Q->front = (Q->front + 1) % MAXQSIZE;
    return 1;
}

int main(void)
{
    SqQueue Q;
    ElemType e = 0;
    int v = 10, i;
    if (!InitQueue(&Q)) { printf("malloc failed\n"); return 1; }

    for (i = 0; i < 5; i++) {
        EnQueue(&Q, v); printf("入队 %2d  rear=%d\n", v, Q.rear); v += 10;
    }
    printf("入队 %2d -> %s\n", v, EnQueue(&Q, v) ? "ok" : "队满(少用一个单元)");
    printf("length=%d front=%d rear=%d\n", QueueLength(&Q), Q.front, Q.rear);

    for (i = 0; i < 3; i++) { DeQueue(&Q, &e); printf("出队 %2d  front=%d\n", e, Q.front); }
    EnQueue(&Q, v); printf("入队 %2d  rear=%d  <- rear 回绕到 0\n", v, Q.rear); v += 10;
    EnQueue(&Q, v); printf("入队 %2d  rear=%d\n", v, Q.rear); v += 10;
    printf("length=%d front=%d rear=%d\n", QueueLength(&Q), Q.front, Q.rear);

    printf("全部出队:");
    while (!QueueEmpty(&Q)) { DeQueue(&Q, &e); printf(" %d", e); }
    printf("\nempty=%d\n", QueueEmpty(&Q));
    free(Q.base);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef char ElemType;
typedef struct QNode { ElemType data; struct QNode *next; } QNode, *QueuePtr;
typedef struct { QueuePtr front, rear; } LinkQueue;

int InitQueue(LinkQueue *Q)
{
    Q->front = Q->rear = (QueuePtr)malloc(sizeof(QNode));   /* 头结点 */
    if (Q->front == NULL) return 0;
    Q->front->next = NULL;
    return 1;
}

int EnQueue(LinkQueue *Q, ElemType e)
{
    QueuePtr s = (QueuePtr)malloc(sizeof(QNode));
    if (s == NULL) return 0;
    s->data = e; s->next = NULL;
    Q->rear->next = s;
    Q->rear = s;
    return 1;
}

int DeQueue(LinkQueue *Q, ElemType *e)
{
    QueuePtr p;
    if (Q->front == Q->rear) return 0;        /* 队空 */
    p = Q->front->next;                       /* 队头元素结点 */
    *e = p->data;
    Q->front->next = p->next;
    if (Q->rear == p) Q->rear = Q->front;     /* ★ 删的是最后一个元素 */
    free(p);
    return 1;
}

int main(void)
{
    LinkQueue Q;
    ElemType e = 0;
    QueuePtr p;
    if (!InitQueue(&Q)) { printf("malloc failed\n"); return 1; }

    EnQueue(&Q, 'a'); EnQueue(&Q, 'b'); EnQueue(&Q, 'c');
    printf("队列:");
    for (p = Q.front->next; p != NULL; p = p->next) printf(" %c", p->data);
    printf("\n");
    DeQueue(&Q, &e); printf("出队 %c\n", e);
    DeQueue(&Q, &e); printf("出队 %c\n", e);
    DeQueue(&Q, &e); printf("出队 %c  <- 这是最后一个元素\n", e);
    printf("rear 已修正: front==rear ? %d\n", Q.front == Q.rear);
    printf("再出队 -> %s\n", DeQueue(&Q, &e) ? "ok" : "队空，失败");
    EnQueue(&Q, 'z');
    printf("重新入队 z -> front==rear ? %d, data=%c\n",
           Q.front == Q.rear, Q.rear->data);
    free(Q.front);
    return 0;
}

#include <stdio.h>

#define STACKSIZE 64

static void convert(int n, int d)
{
    int st[STACKSIZE], top = 0, i;
    printf("%d 的 %d 进制 = ", n, d);
    if (n == 0) st[top++] = 0;             /* 0 的特殊情况 */
    while (n > 0) { st[top++] = n % d; n /= d; }   /* 余数入栈 */
    for (i = top - 1; i >= 0; i--) {       /* 逆序出栈 */
        if (st[i] < 10) printf("%d", st[i]);
        else            printf("%c", 'A' + st[i] - 10);
    }
    printf("\n");
}

int main(void)
{
    convert(1348, 8);
    convert(255, 16);
    convert(0, 8);
    convert(10, 2);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXOP 32

int main(void)
{
    const char *expr = "6 2 3 + * 4 -";
    double st[MAXOP];
    int top = 0;
    const char *p = expr;
    char tok[16];

    printf("后缀表达式: %s\n", expr);
    while (*p != '\0') {
        while (*p == ' ') p++;                     /* 跳过空白 */
        if (*p == '\0') break;
        {
            int i = 0;
            while (*p != '\0' && *p != ' ') tok[i++] = *p++;
            tok[i] = '\0';                         /* 取出一个单词 */
        }
        if (strlen(tok) == 1 && strchr("+-*/", tok[0]) != NULL) {
            double b = st[--top];                  /* 先弹出的是右操作数 */
            double a = st[--top];
            switch (tok[0]) {
            case '+': st[top++] = a + b; break;
            case '-': st[top++] = a - b; break;
            case '*': st[top++] = a * b; break;
            default : st[top++] = a / b; break;
            }
            printf("  %g %s %g = %g\n", a, tok, b, st[top - 1]);
        } else {
            st[top++] = atof(tok);
            printf("  push %s\n", tok);
        }
    }
    printf("结果 = %g\n", st[--top]);
    return 0;
}
